const IMP_LABEL = { customer_code: 'รหัสลูกค้า', full_name: 'ชื่อ', last_name: 'นามสกุล', phone: 'โทรศัพท์', budget_thb: 'งบประมาณ', lifestyle: 'ไลฟ์สไตล์', notes: 'หมายเหตุ', exam_date: 'วันที่ตรวจ', pd: 'PD', add_power: 'ADD' };
